using System.Collections.Generic;

namespace WelfareManagement
{
    // English strings for the Options page. Key convention: "<name>.L" = label, "<name>.D" = description.
    // English only at launch; Get() falls back to English (the key's value) for every locale.
    public static class Translations
    {
        public static string Get(string key, string locale) =>
            (Loc.TryGetValue(locale, out var lm) && lm.TryGetValue(key, out var lv)) ? lv
            : (En.TryGetValue(key, out var v) ? v : key);

        public static readonly Dictionary<string, string> En = new Dictionary<string, string>
        {
            { "mod.name", "Realistic Funding & Management: Welfare Benefits" },
            { "tab.main", "Main" },
            { "group.benefits", "Citizen benefits" },
            { "group.general", "General" },

            { "enabled.L", "Enable Welfare Management" },
            { "enabled.D", "Master switch for the whole mod. Off = exact vanilla: benefit amounts return to base-game values and the treasury is charged nothing; your other settings below are kept. On by default." },

            { "benefitsFunded.L", "Fund benefits from the treasury" },
            { "benefitsFunded.D", "Vanilla mints pensions, unemployment and family allowance for free. When on, the real daily outlay is deducted from the city treasury and shown as a budget expense (Subsidies) — but only while a welfare office is present to administer it. With this ON and NO welfare office, benefits are NOT charged to the treasury: they fall back to the base-game default (still paid, minted free), so your city keeps growing normally. Build a welfare office to actually fund benefits from the treasury. Off = vanilla behaviour." },
            { "benefitsFunded.W", "No welfare office in your city yet, so benefits aren't being funded from the treasury — they're paid by the base game (free) instead. Build a welfare office to fund them from the treasury." },

            { "pension.L", "Pension amount" },
            { "pension.D", "Scales the pension paid to each elderly non-worker. 100% = vanilla." },

            { "unemployment.L", "Unemployment benefit amount" },
            { "unemployment.D", "Scales the unemployment benefit paid to each out-of-work adult (only while inside the allowance window). 100% = vanilla." },

            { "family.L", "Family allowance amount" },
            { "family.D", "Scales the family allowance paid for each child or teen. 100% = vanilla." },

                    { "ui.perRecipient", "₡{v}/mo per recipient" },
            { "ui.buttonTooltip", "Realistic Funding & Management: Welfare Benefits" },
            { "ui.panelTitle", "Welfare Benefits" },
            { "ui.benefitsHeader", "CITIZEN BENEFITS" },
            { "ui.fundedOn", "Funded by treasury: ON" },
            { "ui.fundedOff", "Funded by treasury: OFF" },
            { "ui.noCost", "no cost" },
            { "ui.benefitsNote", "% of vanilla. With funding on, the treasury cost is shown per hour (matching the money trend)." },
            { "ui.welfareWarning", "No welfare office in the city — benefits are paid by the base game (free) and not charged to the treasury. Build a Welfare Office to fund them from the treasury." },
            { "ui.welfareAdmin", "administered by {n} welfare office(s)" },
            { "ui.benefitsRow", "Citizen Benefits" },
            { "ui.hoverBenefits", "Vanilla creates pension, unemployment and family-allowance money out of thin air. With treasury funding on, the mod counts each recipient every in-game day — the elderly (pension), jobless adults still inside the unemployment allowance window, and children (family allowance) — multiplies them by the current benefit amounts, and deducts the total from your city balance as this expense." },
};
            public static readonly System.Collections.Generic.Dictionary<string, System.Collections.Generic.Dictionary<string, string>> Loc =
            new System.Collections.Generic.Dictionary<string, System.Collections.Generic.Dictionary<string, string>>
            {
                ["de-DE"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Allgemein", ["group.benefits"]="Bürgerleistungen", ["group.general"]="Allgemein", ["enabled.L"]="Welfare Management aktivieren", ["enabled.D"]="Hauptschalter für den gesamten Mod. Aus = exakt Vanilla: Leistungsbeträge kehren zu den Grundspielwerten zurück und die Stadtkasse wird nicht belastet; deine übrigen Einstellungen unten bleiben erhalten. Standardmäßig AN.", ["benefitsFunded.L"]="Leistungen aus der Stadtkasse finanzieren", ["benefitsFunded.D"]="Vanilla erschafft Renten, Arbeitslosen- und Familiengeld kostenlos. Wenn aktiviert, werden die echten täglichen Ausgaben von der Stadtkasse abgezogen und als Budgetausgabe (Subventionen) angezeigt — aber nur solange ein Sozialamt vorhanden ist, um sie zu verwalten. Mit dieser Option AN und OHNE Sozialamt werden Leistungen NICHT der Stadtkasse belastet: sie fallen auf den Grundspiel-Standard zurück (weiterhin gezahlt, kostenlos erschaffen), sodass deine Stadt normal weiterwächst. Baue ein Sozialamt, um Leistungen tatsächlich aus der Stadtkasse zu finanzieren. Aus = Vanilla-Verhalten.", ["benefitsFunded.W"]="Noch kein Sozialamt in deiner Stadt, daher werden Leistungen nicht aus der Stadtkasse finanziert — sie werden stattdessen vom Grundspiel (kostenlos) gezahlt. Baue ein Sozialamt, um sie aus der Stadtkasse zu finanzieren.", ["pension.L"]="Rentenbetrag", ["pension.D"]="Skaliert die Rente, die an jeden älteren Nichtarbeiter gezahlt wird. 100 % = Vanilla.", ["unemployment.L"]="Höhe des Arbeitslosengeldes", ["unemployment.D"]="Skaliert das Arbeitslosengeld, das an jeden arbeitslosen Erwachsenen gezahlt wird (nur innerhalb des Anspruchszeitraums). 100 % = Vanilla.", ["family.L"]="Höhe des Familiengeldes", ["family.D"]="Skaliert das Familiengeld, das für jedes Kind oder jeden Jugendlichen gezahlt wird. 100 % = Vanilla.", ["ui.perRecipient"]="₡{v}/Mon. pro Empfänger", ["ui.buttonTooltip"]="Realistic Funding & Management: Welfare Benefits", ["ui.panelTitle"]="Sozialleistungen", ["ui.benefitsHeader"]="BÜRGERLEISTUNGEN", ["ui.fundedOn"]="Aus Stadtkasse finanziert: AN", ["ui.fundedOff"]="Aus Stadtkasse finanziert: AUS", ["ui.noCost"]="keine Kosten", ["ui.benefitsNote"]="% von Vanilla. Bei aktivierter Finanzierung werden die Stadtkassenkosten pro Stunde angezeigt (passend zum Geldtrend).", ["ui.welfareWarning"]="Kein Sozialamt in der Stadt — Leistungen werden vom Grundspiel (kostenlos) gezahlt und nicht der Stadtkasse belastet. Baue ein Sozialamt, um sie aus der Stadtkasse zu finanzieren.", ["ui.welfareAdmin"]="verwaltet von {n} Sozialamt/-ämtern", ["ui.benefitsRow"]="Bürgerleistungen", ["ui.hoverBenefits"]="Vanilla erschafft Renten-, Arbeitslosen- und Familiengeld aus dem Nichts. Bei aktivierter Finanzierung aus der Stadtkasse zählt der Mod jeden Empfänger an jedem Spieltag — Ältere (Rente), arbeitslose Erwachsene noch innerhalb des Arbeitslosengeld-Anspruchszeitraums und Kinder (Familiengeld) — multipliziert sie mit den aktuellen Leistungsbeträgen und zieht die Summe als diese Ausgabe von deinem Stadtguthaben ab.", },
                ["es-ES"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Principal", ["group.benefits"]="Prestaciones ciudadanas", ["group.general"]="General", ["enabled.L"]="Activar Welfare Management", ["enabled.D"]="Interruptor principal de todo el mod. Desactivado = vanilla exacto: los importes de las prestaciones vuelven a los valores del juego base y no se carga nada al tesoro; el resto de tus ajustes de abajo se conservan. Activado por defecto.", ["benefitsFunded.L"]="Financiar las prestaciones con el tesoro", ["benefitsFunded.D"]="El vanilla crea de la nada las pensiones, el subsidio de desempleo y la prestación familiar. Cuando está activado, el gasto diario real se descuenta del tesoro de la ciudad y se muestra como gasto del presupuesto (Subvenciones), pero solo mientras haya una oficina de bienestar que lo administre. Con esto ACTIVADO y SIN oficina de bienestar, las prestaciones NO se cargan al tesoro: se recurre al valor por defecto del juego base (se siguen pagando, creadas gratis), de modo que tu ciudad sigue creciendo con normalidad. Construye una oficina de bienestar para financiar realmente las prestaciones con el tesoro. Desactivado = comportamiento vanilla.", ["benefitsFunded.W"]="Todavía no hay ninguna oficina de bienestar en tu ciudad, así que las prestaciones no se financian con el tesoro: las paga el juego base (gratis). Construye una oficina de bienestar para financiarlas con el tesoro.", ["pension.L"]="Importe de la pensión", ["pension.D"]="Escala la pensión pagada a cada anciano no trabajador. 100% = vanilla.", ["unemployment.L"]="Importe del subsidio de desempleo", ["unemployment.D"]="Escala el subsidio de desempleo pagado a cada adulto sin trabajo (solo mientras esté dentro del periodo de prestación). 100% = vanilla.", ["family.L"]="Importe de la prestación familiar", ["family.D"]="Escala la prestación familiar pagada por cada niño o adolescente. 100% = vanilla.", ["ui.perRecipient"]="₡{v}/mes por beneficiario", ["ui.buttonTooltip"]="Realistic Funding & Management: Welfare Benefits", ["ui.panelTitle"]="Prestaciones de bienestar", ["ui.benefitsHeader"]="PRESTACIONES CIUDADANAS", ["ui.fundedOn"]="Financiado por el tesoro: SÍ", ["ui.fundedOff"]="Financiado por el tesoro: NO", ["ui.noCost"]="sin coste", ["ui.benefitsNote"]="% del vanilla. Con la financiación activada, el coste del tesoro se muestra por hora (acorde con la tendencia del dinero).", ["ui.welfareWarning"]="No hay ninguna oficina de bienestar en la ciudad: las prestaciones las paga el juego base (gratis) y no se cargan al tesoro. Construye una oficina de bienestar para financiarlas con el tesoro.", ["ui.welfareAdmin"]="administrado por {n} oficina(s) de bienestar", ["ui.benefitsRow"]="Prestaciones ciudadanas", ["ui.hoverBenefits"]="El vanilla crea de la nada el dinero de las pensiones, el desempleo y la prestación familiar. Con la financiación del tesoro activada, el mod cuenta cada beneficiario en cada día del juego —los ancianos (pensión), los adultos sin trabajo que aún están dentro del periodo del subsidio de desempleo y los niños (prestación familiar)—, los multiplica por los importes actuales de las prestaciones y descuenta el total del balance de tu ciudad como este gasto.", },
                ["fr-FR"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Principal", ["group.benefits"]="Prestations aux citoyens", ["group.general"]="Général", ["enabled.L"]="Activer Welfare Management", ["enabled.D"]="Interrupteur principal de tout le mod. Désactivé = jeu de base exact : les montants des prestations reviennent aux valeurs du jeu de base et le trésor n'est débité de rien ; vos autres réglages ci-dessous sont conservés. Activé par défaut.", ["benefitsFunded.L"]="Financer les prestations depuis le trésor", ["benefitsFunded.D"]="Le jeu de base crée gratuitement les retraites, allocations chômage et allocations familiales. Lorsque cette option est activée, la dépense quotidienne réelle est déduite du trésor de la ville et affichée comme dépense budgétaire (Subventions) — mais uniquement tant qu'un bureau d'aide sociale est présent pour l'administrer. Avec cette option ACTIVÉE et AUCUN bureau d'aide sociale, les prestations ne sont PAS débitées du trésor : elles reviennent au comportement par défaut du jeu de base (toujours versées, créées gratuitement), pour que votre ville continue de croître normalement. Construisez un bureau d'aide sociale pour financer réellement les prestations depuis le trésor. Désactivé = comportement du jeu de base.", ["benefitsFunded.W"]="Aucun bureau d'aide sociale dans votre ville pour l'instant, donc les prestations ne sont pas financées depuis le trésor — elles sont versées par le jeu de base (gratuitement). Construisez un bureau d'aide sociale pour les financer depuis le trésor.", ["pension.L"]="Montant de la retraite", ["pension.D"]="Ajuste la retraite versée à chaque personne âgée sans emploi. 100 % = jeu de base.", ["unemployment.L"]="Montant de l'allocation chômage", ["unemployment.D"]="Ajuste l'allocation chômage versée à chaque adulte sans emploi (uniquement pendant la période d'éligibilité). 100 % = jeu de base.", ["family.L"]="Montant de l'allocation familiale", ["family.D"]="Ajuste l'allocation familiale versée pour chaque enfant ou adolescent. 100 % = jeu de base.", ["ui.perRecipient"]="₡{v}/mois par bénéficiaire", ["ui.buttonTooltip"]="Financement et gestion réalistes : prestations sociales", ["ui.panelTitle"]="Prestations sociales", ["ui.benefitsHeader"]="PRESTATIONS AUX CITOYENS", ["ui.fundedOn"]="Financé par le trésor : ACTIVÉ", ["ui.fundedOff"]="Financé par le trésor : DÉSACTIVÉ", ["ui.noCost"]="sans coût", ["ui.benefitsNote"]="% du jeu de base. Avec le financement activé, le coût pour le trésor est affiché par heure (correspondant à la tendance monétaire).", ["ui.welfareWarning"]="Aucun bureau d'aide sociale dans la ville — les prestations sont versées par le jeu de base (gratuitement) et ne sont pas débitées du trésor. Construisez un bureau d'aide sociale pour les financer depuis le trésor.", ["ui.welfareAdmin"]="administré par {n} bureau(x) d'aide sociale", ["ui.benefitsRow"]="Prestations aux citoyens", ["ui.hoverBenefits"]="Le jeu de base crée l'argent des retraites, allocations chômage et allocations familiales à partir de rien. Avec le financement par le trésor activé, le mod compte chaque bénéficiaire à chaque jour en jeu — les personnes âgées (retraite), les adultes sans emploi encore dans la période d'éligibilité au chômage, et les enfants (allocation familiale) — les multiplie par les montants de prestations actuels, et déduit le total du solde de votre ville sous forme de cette dépense.", },
                ["it-IT"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Principale", ["group.benefits"]="Sussidi ai cittadini", ["group.general"]="Generale", ["enabled.L"]="Abilita Welfare Management", ["enabled.D"]="Interruttore principale dell'intera mod. Disattivato = comportamento originale esatto: gli importi dei sussidi tornano ai valori del gioco base e alla tesoreria non viene addebitato nulla; le altre impostazioni qui sotto vengono conservate. Attivato per impostazione predefinita.", ["benefitsFunded.L"]="Finanzia i sussidi dalla tesoreria", ["benefitsFunded.D"]="Il gioco base crea gratuitamente pensioni, indennità di disoccupazione e assegni familiari. Quando è attivo, l'esborso giornaliero reale viene detratto dalla tesoreria cittadina e mostrato come spesa di bilancio (Sussidi) — ma solo se è presente un ufficio assistenziale che lo amministra. Con questa opzione ATTIVA e NESSUN ufficio assistenziale, i sussidi NON vengono addebitati alla tesoreria: si ripiega sul comportamento predefinito del gioco base (pagati comunque, creati gratuitamente), così la tua città continua a crescere normalmente. Costruisci un ufficio assistenziale per finanziare davvero i sussidi dalla tesoreria. Disattivato = comportamento originale.", ["benefitsFunded.W"]="Nella tua città non c'è ancora un ufficio assistenziale, quindi i sussidi non vengono finanziati dalla tesoreria — sono pagati dal gioco base (gratuitamente). Costruisci un ufficio assistenziale per finanziarli dalla tesoreria.", ["pension.L"]="Importo della pensione", ["pension.D"]="Scala la pensione pagata a ogni anziano non lavoratore. 100% = originale.", ["unemployment.L"]="Importo dell'indennità di disoccupazione", ["unemployment.D"]="Scala l'indennità di disoccupazione pagata a ogni adulto senza lavoro (solo entro la finestra di erogazione). 100% = originale.", ["family.L"]="Importo dell'assegno familiare", ["family.D"]="Scala l'assegno familiare pagato per ogni bambino o adolescente. 100% = originale.", ["ui.perRecipient"]="₡{v}/mese per beneficiario", ["ui.buttonTooltip"]="Realistic Funding & Management: Welfare Benefits", ["ui.panelTitle"]="Sussidi assistenziali", ["ui.benefitsHeader"]="SUSSIDI AI CITTADINI", ["ui.fundedOn"]="Finanziati dalla tesoreria: ATTIVO", ["ui.fundedOff"]="Finanziati dalla tesoreria: DISATTIVO", ["ui.noCost"]="nessun costo", ["ui.benefitsNote"]="% dell'originale. Con il finanziamento attivo, il costo per la tesoreria è mostrato all'ora (coerente con l'andamento del denaro).", ["ui.welfareWarning"]="Nessun ufficio assistenziale nella città — i sussidi sono pagati dal gioco base (gratuitamente) e non addebitati alla tesoreria. Costruisci un ufficio assistenziale per finanziarli dalla tesoreria.", ["ui.welfareAdmin"]="amministrati da {n} ufficio/i assistenziale/i", ["ui.benefitsRow"]="Sussidi ai cittadini", ["ui.hoverBenefits"]="Il gioco base crea dal nulla il denaro per pensioni, disoccupazione e assegni familiari. Con il finanziamento dalla tesoreria attivo, la mod conta ogni beneficiario per ciascun giorno di gioco — gli anziani (pensione), gli adulti disoccupati ancora entro la finestra dell'indennità di disoccupazione e i bambini (assegno familiare) — li moltiplica per gli importi attuali dei sussidi e detrae il totale dal saldo della tua città come questa spesa.", },
                ["ja-JP"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="メイン", ["group.benefits"]="市民給付", ["group.general"]="全般", ["enabled.L"]="Welfare Management を有効化", ["enabled.D"]="Mod全体のマスタースイッチ。オフ = 完全にバニラ状態: 給付額がベースゲームの値に戻り、国庫には一切請求されません。以下の他の設定は保持されます。デフォルトはオンです。", ["benefitsFunded.L"]="国庫から給付を支出", ["benefitsFunded.D"]="バニラでは年金・失業給付・家族手当が無償で発行されます。オンにすると、実際の日次支出が市の国庫から差し引かれ、予算の支出（補助金）として表示されます。ただし、それを運営する福祉事務所がある場合に限ります。この設定をオンにしても福祉事務所がない場合、給付は国庫に請求されません。ベースゲームのデフォルト（無償で発行され支払われる）にフォールバックするため、市は通常どおり成長し続けます。国庫から給付を実際に支出するには福祉事務所を建設してください。オフ = バニラの挙動。", ["benefitsFunded.W"]="市内にまだ福祉事務所がないため、給付は国庫から支出されていません。代わりにベースゲームによって（無償で）支払われています。国庫から支出するには福祉事務所を建設してください。", ["pension.L"]="年金額", ["pension.D"]="各高齢の無職者に支払われる年金を調整します。100% = バニラ。", ["unemployment.L"]="失業給付額", ["unemployment.D"]="各失業中の成人に支払われる失業給付を調整します（給付期間内に限る）。100% = バニラ。", ["family.L"]="家族手当額", ["family.D"]="各子供または未成年に支払われる家族手当を調整します。100% = バニラ。", ["ui.perRecipient"]="受給者1人あたり ₡{v}/月", ["ui.buttonTooltip"]="Realistic Funding & Management: Welfare Benefits", ["ui.panelTitle"]="市民給付", ["ui.benefitsHeader"]="市民給付", ["ui.fundedOn"]="国庫からの支出: オン", ["ui.fundedOff"]="国庫からの支出: オフ", ["ui.noCost"]="費用なし", ["ui.benefitsNote"]="バニラに対する%。支出をオンにすると、国庫の費用は1時間あたりで表示されます（収支トレンドと一致）。", ["ui.welfareWarning"]="市内に福祉事務所がありません。給付はベースゲームによって（無償で）支払われ、国庫には請求されません。国庫から支出するには福祉事務所を建設してください。", ["ui.welfareAdmin"]="{n}か所の福祉事務所が運営", ["ui.benefitsRow"]="市民給付", ["ui.hoverBenefits"]="バニラでは年金・失業給付・家族手当のお金が何もないところから生み出されます。国庫からの支出をオンにすると、Modはゲーム内の毎日、各受給者（高齢者は年金、失業給付期間内のまだ職のない成人、子供は家族手当）を集計し、現在の給付額を掛け合わせ、その合計を市の収支からこの支出として差し引きます。", },
                ["ko-KR"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="메인", ["group.benefits"]="시민 복지 수당", ["group.general"]="일반", ["enabled.L"]="복지 관리 활성화", ["enabled.D"]="모드 전체의 주 스위치입니다. 꺼짐 = 완전한 기본 게임: 수당 금액이 기본 게임 값으로 돌아가고 국고에서는 아무것도 청구되지 않습니다. 아래의 다른 설정은 유지됩니다. 기본값은 켜짐입니다.", ["benefitsFunded.L"]="국고에서 복지 수당 지급", ["benefitsFunded.D"]="기본 게임은 연금, 실업 수당, 가족 수당을 무료로 발행합니다. 이 옵션을 켜면 실제 일일 지출이 도시 국고에서 차감되어 예산 지출(보조금)로 표시됩니다 — 단, 이를 관리할 복지 사무소가 있을 때만 그렇습니다. 이 옵션이 켜져 있고 복지 사무소가 없으면 수당은 국고에서 청구되지 않습니다: 기본 게임 기본값으로 대체되어(여전히 지급되며 무료로 발행됨) 도시가 정상적으로 계속 성장합니다. 국고에서 실제로 수당을 지급하려면 복지 사무소를 건설하세요. 꺼짐 = 기본 게임 동작.", ["benefitsFunded.W"]="아직 도시에 복지 사무소가 없어 수당이 국고에서 지급되지 않고 있습니다 — 기본 게임이 무료로 지급합니다. 국고에서 지급하려면 복지 사무소를 건설하세요.", ["pension.L"]="연금 금액", ["pension.D"]="일하지 않는 노인 각자에게 지급되는 연금을 조정합니다. 100% = 기본 게임.", ["unemployment.L"]="실업 수당 금액", ["unemployment.D"]="실직 성인 각자에게 지급되는 실업 수당을 조정합니다(수급 기간 이내인 경우에만). 100% = 기본 게임.", ["family.L"]="가족 수당 금액", ["family.D"]="각 아동 또는 청소년에게 지급되는 가족 수당을 조정합니다. 100% = 기본 게임.", ["ui.perRecipient"]="수급자당 ₡{v}/월", ["ui.buttonTooltip"]="현실적 재정 및 관리: 복지 수당", ["ui.panelTitle"]="복지 수당", ["ui.benefitsHeader"]="시민 복지 수당", ["ui.fundedOn"]="국고 지급: 켜짐", ["ui.fundedOff"]="국고 지급: 꺼짐", ["ui.noCost"]="비용 없음", ["ui.benefitsNote"]="기본 게임 대비 %. 국고 지급이 켜진 경우, 국고 비용은 시간당으로 표시됩니다(자금 추세와 일치).", ["ui.welfareWarning"]="도시에 복지 사무소가 없습니다 — 수당은 기본 게임이 무료로 지급하며 국고에서 청구되지 않습니다. 국고에서 지급하려면 복지 사무소를 건설하세요.", ["ui.welfareAdmin"]="복지 사무소 {n}곳에서 관리", ["ui.benefitsRow"]="시민 복지 수당", ["ui.hoverBenefits"]="기본 게임은 연금, 실업 수당, 가족 수당을 무에서 만들어 냅니다. 국고 지급이 켜지면 모드가 게임 내 매일 각 수급자를 집계합니다 — 노인(연금), 실업 수급 기간 이내의 무직 성인, 아동(가족 수당) — 이를 현재 수당 금액과 곱한 뒤 그 합계를 도시 잔액에서 이 지출로 차감합니다.", },
                ["pl-PL"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Główne", ["group.benefits"]="Świadczenia dla obywateli", ["group.general"]="Ogólne", ["enabled.L"]="Włącz Welfare Management", ["enabled.D"]="Główny przełącznik całego moda. Wyłączony = dokładnie jak w grze podstawowej: kwoty świadczeń wracają do wartości gry podstawowej, a skarbiec nie jest niczym obciążany; pozostałe ustawienia poniżej są zachowane. Domyślnie włączony.", ["benefitsFunded.L"]="Finansuj świadczenia ze skarbca", ["benefitsFunded.D"]="Gra podstawowa wykreowuje emerytury, zasiłki dla bezrobotnych i zasiłki rodzinne za darmo. Gdy opcja jest włączona, rzeczywisty dzienny wydatek jest odejmowany ze skarbca miasta i pokazywany jako wydatek budżetowy (Dotacje) — ale tylko wtedy, gdy istnieje urząd opieki społecznej, który tym administruje. Przy tej opcji WŁĄCZONEJ i BRAKU urzędu opieki społecznej świadczenia NIE są pobierane ze skarbca: wracają do domyślnych wartości gry podstawowej (nadal wypłacane, kreowane za darmo), więc twoje miasto nadal rozwija się normalnie. Zbuduj urząd opieki społecznej, aby faktycznie finansować świadczenia ze skarbca. Wyłączone = zachowanie z gry podstawowej.", ["benefitsFunded.W"]="W twoim mieście nie ma jeszcze urzędu opieki społecznej, więc świadczenia nie są finansowane ze skarbca — zamiast tego wypłaca je gra podstawowa (za darmo). Zbuduj urząd opieki społecznej, aby finansować je ze skarbca.", ["pension.L"]="Kwota emerytury", ["pension.D"]="Skaluje emeryturę wypłacaną każdemu niepracującemu seniorowi. 100% = gra podstawowa.", ["unemployment.L"]="Kwota zasiłku dla bezrobotnych", ["unemployment.D"]="Skaluje zasiłek dla bezrobotnych wypłacany każdemu bezrobotnemu dorosłemu (tylko w okresie przysługiwania zasiłku). 100% = gra podstawowa.", ["family.L"]="Kwota zasiłku rodzinnego", ["family.D"]="Skaluje zasiłek rodzinny wypłacany na każde dziecko lub nastolatka. 100% = gra podstawowa.", ["ui.perRecipient"]="₡{v}/mies. na odbiorcę", ["ui.buttonTooltip"]="Realistyczne finansowanie i zarządzanie: Świadczenia socjalne", ["ui.panelTitle"]="Świadczenia socjalne", ["ui.benefitsHeader"]="ŚWIADCZENIA DLA OBYWATELI", ["ui.fundedOn"]="Finansowane ze skarbca: WŁ.", ["ui.fundedOff"]="Finansowane ze skarbca: WYŁ.", ["ui.noCost"]="bez kosztów", ["ui.benefitsNote"]="% wartości gry podstawowej. Przy włączonym finansowaniu koszt dla skarbca jest pokazywany na godzinę (zgodnie z trendem finansowym).", ["ui.welfareWarning"]="Brak urzędu opieki społecznej w mieście — świadczenia wypłaca gra podstawowa (za darmo) i nie obciążają one skarbca. Zbuduj urząd opieki społecznej, aby finansować je ze skarbca.", ["ui.welfareAdmin"]="administrowane przez {n} urząd(-ów) opieki społecznej", ["ui.benefitsRow"]="Świadczenia dla obywateli", ["ui.hoverBenefits"]="Gra podstawowa tworzy pieniądze na emerytury, zasiłki dla bezrobotnych i zasiłki rodzinne z powietrza. Przy włączonym finansowaniu ze skarbca mod codziennie (w czasie gry) zlicza każdego odbiorcę — seniorów (emerytura), bezrobotnych dorosłych wciąż w okresie przysługiwania zasiłku oraz dzieci (zasiłek rodzinny) — mnoży ich przez bieżące kwoty świadczeń i odejmuje sumę od salda miasta jako ten wydatek.", },
                ["pt-BR"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Principal", ["group.benefits"]="Benefícios aos cidadãos", ["group.general"]="Geral", ["enabled.L"]="Ativar Welfare Management", ["enabled.D"]="Interruptor mestre de todo o mod. Desativado = jogo original exato: os valores dos benefícios voltam aos valores do jogo base e nada é cobrado do tesouro; suas demais configurações abaixo são mantidas. Ativado por padrão.", ["benefitsFunded.L"]="Financiar benefícios pelo tesouro", ["benefitsFunded.D"]="O jogo original cria aposentadorias, seguro-desemprego e salário-família de graça. Quando ativado, o desembolso diário real é descontado do tesouro da cidade e exibido como uma despesa orçamentária (Subsídios) — mas apenas enquanto houver um escritório de assistência social para administrá-lo. Com isto ATIVADO e SEM escritório de assistência social, os benefícios NÃO são cobrados do tesouro: eles voltam ao padrão do jogo base (ainda pagos, criados de graça), então sua cidade continua crescendo normalmente. Construa um escritório de assistência social para de fato financiar os benefícios pelo tesouro. Desativado = comportamento original.", ["benefitsFunded.W"]="Ainda não há escritório de assistência social na sua cidade, então os benefícios não estão sendo financiados pelo tesouro — eles são pagos pelo jogo base (de graça). Construa um escritório de assistência social para financiá-los pelo tesouro.", ["pension.L"]="Valor da aposentadoria", ["pension.D"]="Ajusta a aposentadoria paga a cada idoso não trabalhador. 100% = original.", ["unemployment.L"]="Valor do seguro-desemprego", ["unemployment.D"]="Ajusta o seguro-desemprego pago a cada adulto sem emprego (apenas enquanto estiver dentro do período de concessão). 100% = original.", ["family.L"]="Valor do salário-família", ["family.D"]="Ajusta o salário-família pago por cada criança ou adolescente. 100% = original.", ["ui.perRecipient"]="₡{v}/mês por beneficiário", ["ui.buttonTooltip"]="Financiamento e Gestão Realista: Benefícios Sociais", ["ui.panelTitle"]="Benefícios Sociais", ["ui.benefitsHeader"]="BENEFÍCIOS AOS CIDADÃOS", ["ui.fundedOn"]="Financiado pelo tesouro: LIGADO", ["ui.fundedOff"]="Financiado pelo tesouro: DESLIGADO", ["ui.noCost"]="sem custo", ["ui.benefitsNote"]="% do original. Com o financiamento ligado, o custo do tesouro é exibido por hora (correspondendo à tendência de dinheiro).", ["ui.welfareWarning"]="Nenhum escritório de assistência social na cidade — os benefícios são pagos pelo jogo base (de graça) e não são cobrados do tesouro. Construa um Escritório de Assistência Social para financiá-los pelo tesouro.", ["ui.welfareAdmin"]="administrado por {n} escritório(s) de assistência social", ["ui.benefitsRow"]="Benefícios aos Cidadãos", ["ui.hoverBenefits"]="O jogo original cria dinheiro de aposentadoria, seguro-desemprego e salário-família do nada. Com o financiamento pelo tesouro ligado, o mod conta cada beneficiário a cada dia do jogo — os idosos (aposentadoria), adultos desempregados ainda dentro do período de concessão do seguro-desemprego, e crianças (salário-família) — multiplica-os pelos valores atuais dos benefícios e desconta o total do saldo da sua cidade como esta despesa.", },
                ["ru-RU"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="Основное", ["group.benefits"]="Пособия горожан", ["group.general"]="Общие", ["enabled.L"]="Включить Welfare Management", ["enabled.D"]="Главный переключатель всего мода. Выкл = точно как в оригинале: размеры пособий возвращаются к базовым значениям игры, и с казны ничего не списывается; ваши остальные настройки ниже сохраняются. По умолчанию ВКЛ.", ["benefitsFunded.L"]="Финансировать пособия из казны", ["benefitsFunded.D"]="Оригинал создаёт пенсии, пособия по безработице и семейные пособия бесплатно. При включении реальные ежедневные расходы вычитаются из городской казны и показываются как статья бюджета (Субсидии) — но только пока есть отдел социального обеспечения для их администрирования. При ВКЛ и БЕЗ отдела социального обеспечения пособия НЕ списываются с казны: они возвращаются к базовому значению игры (по-прежнему выплачиваются, создаются бесплатно), так что ваш город продолжает нормально расти. Постройте отдел социального обеспечения, чтобы действительно финансировать пособия из казны. Выкл = поведение оригинала.", ["benefitsFunded.W"]="В вашем городе пока нет отдела социального обеспечения, поэтому пособия не финансируются из казны — их выплачивает базовая игра (бесплатно). Постройте отдел социального обеспечения, чтобы финансировать их из казны.", ["pension.L"]="Размер пенсии", ["pension.D"]="Масштабирует пенсию, выплачиваемую каждому неработающему пожилому жителю. 100% = оригинал.", ["unemployment.L"]="Размер пособия по безработице", ["unemployment.D"]="Масштабирует пособие по безработице, выплачиваемое каждому безработному взрослому (только в пределах периода действия пособия). 100% = оригинал.", ["family.L"]="Размер семейного пособия", ["family.D"]="Масштабирует семейное пособие, выплачиваемое за каждого ребёнка или подростка. 100% = оригинал.", ["ui.perRecipient"]="₡{v}/мес на получателя", ["ui.buttonTooltip"]="Realistic Funding & Management: Welfare Benefits", ["ui.panelTitle"]="Пособия горожан", ["ui.benefitsHeader"]="ПОСОБИЯ ГОРОЖАН", ["ui.fundedOn"]="Финансирование из казны: ВКЛ", ["ui.fundedOff"]="Финансирование из казны: ВЫКЛ", ["ui.noCost"]="без затрат", ["ui.benefitsNote"]="% от оригинала. При включённом финансировании стоимость для казны показана за час (в соответствии с трендом денег).", ["ui.welfareWarning"]="В городе нет отдела социального обеспечения — пособия выплачивает базовая игра (бесплатно) и не списывает с казны. Постройте отдел социального обеспечения, чтобы финансировать их из казны.", ["ui.welfareAdmin"]="администрируется отделами социального обеспечения: {n}", ["ui.benefitsRow"]="Пособия горожан", ["ui.hoverBenefits"]="Оригинал создаёт деньги на пенсии, пособия по безработице и семейные пособия из воздуха. При включённом финансировании из казны мод подсчитывает каждого получателя каждый игровой день — пожилых (пенсия), безработных взрослых в пределах периода действия пособия по безработице и детей (семейное пособие) — умножает их на текущие размеры пособий и вычитает итог из баланса вашего города как эту статью расходов.", },
                ["zh-HANS"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="主要", ["group.benefits"]="市民福利", ["group.general"]="常规", ["enabled.L"]="启用福利管理", ["enabled.D"]="整个模组的总开关。关闭 = 完全原版：福利金额恢复为基础游戏数值，国库不产生任何支出；你下方的其他设置将被保留。默认开启。", ["benefitsFunded.L"]="由国库拨款发放福利", ["benefitsFunded.D"]="原版免费凭空发放养老金、失业救济金和家庭津贴。开启后，真实的每日支出将从城市国库扣除，并作为预算支出（补贴）显示——但仅在有福利办公室来管理时才会如此。此项开启且没有福利办公室时，福利不会从国库扣款：它们回退到基础游戏默认方式（仍照常发放，免费凭空生成），因此你的城市照常正常发展。建造福利办公室即可真正由国库拨款发放福利。关闭 = 原版行为。", ["benefitsFunded.W"]="你的城市尚无福利办公室，因此福利并非由国库拨款——而是由基础游戏免费发放。建造福利办公室即可由国库拨款发放。", ["pension.L"]="养老金金额", ["pension.D"]="调整发放给每位不工作老人的养老金。100% = 原版。", ["unemployment.L"]="失业救济金金额", ["unemployment.D"]="调整发放给每位失业成年人的失业救济金（仅在救济期限内）。100% = 原版。", ["family.L"]="家庭津贴金额", ["family.D"]="调整为每名儿童或青少年发放的家庭津贴。100% = 原版。", ["ui.perRecipient"]="₡{v}/月 每位领取者", ["ui.buttonTooltip"]="现实拨款与管理：市民福利", ["ui.panelTitle"]="市民福利", ["ui.benefitsHeader"]="市民福利", ["ui.fundedOn"]="国库拨款：开", ["ui.fundedOff"]="国库拨款：关", ["ui.noCost"]="无花费", ["ui.benefitsNote"]="% 相对原版。开启拨款后，国库成本按每小时显示（与资金走势一致）。", ["ui.welfareWarning"]="城市中没有福利办公室——福利由基础游戏免费发放，不从国库扣款。建造福利办公室即可由国库拨款发放。", ["ui.welfareAdmin"]="由 {n} 个福利办公室管理", ["ui.benefitsRow"]="市民福利", ["ui.hoverBenefits"]="原版凭空创造养老金、失业救济金和家庭津贴。开启国库拨款后，模组每个游戏日统计每位领取者——老人（养老金）、仍在失业救济期限内的失业成年人，以及儿童（家庭津贴）——乘以当前福利金额，并将总额作为此项支出从城市余额中扣除。", },
                ["zh-HANT"] = new System.Collections.Generic.Dictionary<string, string> { ["tab.main"]="主要", ["group.benefits"]="市民福利", ["group.general"]="一般", ["enabled.L"]="啟用福利管理", ["enabled.D"]="整個模組的總開關。關閉＝完全回到原版：福利金額回到遊戲基礎數值，且不向國庫收取任何費用；你下方的其他設定會保留。預設為開啟。", ["benefitsFunded.L"]="由國庫支應福利", ["benefitsFunded.D"]="原版免費發放退休金、失業救濟與家庭津貼。開啟後，實際的每日支出會從城市國庫扣除，並顯示為預算支出（補助）—— 但僅在有福利辦公室負責管理時才會如此。此選項開啟且「沒有」福利辦公室時，福利「不會」向國庫收費：它們會退回遊戲基礎預設（仍照常發放、免費印製），使你的城市繼續正常成長。要真正由國庫支應福利，請興建福利辦公室。關閉＝原版行為。", ["benefitsFunded.W"]="你的城市尚無福利辦公室，因此福利並非由國庫支應 —— 它們改由遊戲基礎系統（免費）發放。興建福利辦公室以由國庫支應。", ["pension.L"]="退休金金額", ["pension.D"]="調整發給每位非就業長者的退休金。100%＝原版。", ["unemployment.L"]="失業救濟金額", ["unemployment.D"]="調整發給每位失業成年人的失業救濟（僅在津貼時效內）。100%＝原版。", ["family.L"]="家庭津貼金額", ["family.D"]="調整為每位兒童或青少年發放的家庭津貼。100%＝原版。", ["ui.perRecipient"]="每名領取者 ₡{v}/月", ["ui.buttonTooltip"]="真實資助與管理：市民福利", ["ui.panelTitle"]="市民福利", ["ui.benefitsHeader"]="市民福利", ["ui.fundedOn"]="由國庫支應：開啟", ["ui.fundedOff"]="由國庫支應：關閉", ["ui.noCost"]="無費用", ["ui.benefitsNote"]="為原版之百分比。開啟資助後，國庫成本以每小時顯示（與資金趨勢一致）。", ["ui.welfareWarning"]="城市中沒有福利辦公室 —— 福利由遊戲基礎系統（免費）發放，不向國庫收費。興建福利辦公室以由國庫支應。", ["ui.welfareAdmin"]="由 {n} 間福利辦公室管理", ["ui.benefitsRow"]="市民福利", ["ui.hoverBenefits"]="原版憑空製造退休金、失業救濟與家庭津貼的錢。開啟國庫資助後，模組每個遊戲內日計算每位領取者 —— 長者（退休金）、仍在失業津貼時效內的失業成年人，以及兒童（家庭津貼）—— 乘上當前的福利金額，並從你的城市餘額中扣除總額作為此項支出。", },
